    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-paused")).toHaveText("no");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ben_2).getByTestId("plan-change-line")).toHaveText([]);
