@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class PlanController {

    /**
     * A plan as the screen shows it, with how many claims it has made so far and its next five plan dates after the
     * sheet's today, and its changes of amount, oldest first.
     */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, List<LocalDate> nextDates, boolean paused, List<ChangeView> changes) {
        static PlanView of(Plan p, LocalDate today) {
            return new PlanView(p.getId(), p.getPersonId(), p.getAmount().toPlainString(), p.getStart(),
                    p.getEvery(), p.getDay(), p.getEnd(), p.getGenerated(), p.nextDates(today, 5),
                    p.isPaused(), p.getChanges().stream().map(ChangeView::of).toList());
        }
    }

    /** A change of a plan's amount: the day it was made and the new amount. */
    public record ChangeView(LocalDate on, String amount) {
        static ChangeView of(PlanChange c) {
            return new ChangeView(c.getChangedOn(), c.getAmount().toPlainString());
        }
    }

    public record AmountForm(@NotNull BigDecimal amount) {
    }

    public record PlanForm(@NotNull BigDecimal amount, @NotNull LocalDate start, Integer every, Integer day,
            @NotNull LocalDate end) {
    }

    /** The claims a generate made, in the order made, and the sheet's plans as they stand. */
    public record GeneratedView(List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService service;
    private final SheetService sheets;

    public PlanController(PlanService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    /** The sheet's plans in the order they were added. */
    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        LocalDate today = sheets.load(sheetId).getToday();
        return service.list(sheetId).stream().map(p -> PlanView.of(p, today)).toList();
    }

    @PostMapping("/people/{personId}/plans")
    public PlanView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @Valid @RequestBody PlanForm form,
            @SessionAttribute(SessionController.USER) String user) {
        Plan added = service.add(user, sheetId, personId, form.amount(), form.start(), form.every(), form.day(),
                form.end());
        return PlanView.of(added, sheets.load(sheetId).getToday());
    }

    /** Pauses or resumes the plan from the sheet's today. */
    @PostMapping("/plans/{planId}/{action:pause|resume}")
    public PlanView pause(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long planId, @PathVariable String action,
            @SessionAttribute(SessionController.USER) String user) {
        Plan plan = service.setPaused(user, sheetId, planId, action.equals("pause"));
        return PlanView.of(plan, sheets.load(sheetId).getToday());
    }

    /** Changes the plan's amount from the sheet's today. */
    @PostMapping("/plans/{planId}/amount")
    public PlanView changeAmount(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long planId, @Valid @RequestBody AmountForm form,
            @SessionAttribute(SessionController.USER) String user) {
        Plan plan = service.changeAmount(user, sheetId, planId, form.amount());
        return PlanView.of(plan, sheets.load(sheetId).getToday());
    }

    /** Makes the plans' claims up to the sheet's today. */
    @ViewerPasses
    @PostMapping("/plans/generate")
    public GeneratedView generate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @SessionAttribute(SessionController.USER) String user) {
        PlanService.Generated g = service.generate(user, sheetId);
        LocalDate today = sheets.load(sheetId).getToday();
        return new GeneratedView(g.claims().stream().map(ClaimView::of).toList(),
                g.plans().stream().map(p -> PlanView.of(p, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * A person's plan: a draft claim of its amount on each plan date, from the start every so many days to the end, or
 * monthly on a day of the month. The plan dates a claim has been made on are kept, so each is made once.
 */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** The interval in days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for a plan every so many days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_claim", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date", nullable = false)
    private Set<LocalDate> made = new HashSet<>();

    /** The plan's pauses, in the order they were made; the last one is open while the plan is paused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    /** The plan's changes of amount, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "pos")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /** The plan's changes of amount, oldest first. */
    public List<PlanChange> getChanges() {
        return changes;
    }

    /** Changes the plan's amount from the day: the claims generated from then on take it. */
    public void changeAmount(LocalDate on, BigDecimal amount) {
        this.amount = amount;
        changes.add(new PlanChange(on, amount));
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    /**
     * The plan's dates from the start up to the last date: every so many days from the start, or the day of the month
     * in every month from the start's month (on the month's last day when it is shorter), those before the start left
     * out.
     */
    public List<LocalDate> datesUpTo(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(every)) {
                dates.add(on);
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate on = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!on.isBefore(start) && !on.isAfter(last)) {
                dates.add(on);
            }
        }
        return dates;
    }

    /**
     * The first plan dates after the day and on or before the end that no pause skips, at most so many of them; none
     * while the plan is paused.
     */
    public List<LocalDate> nextDates(LocalDate after, int count) {
        if (isPaused()) {
            return List.of();
        }
        return datesUpTo(end).stream().filter(on -> on.isAfter(after) && !isSkipped(on)).limit(count).toList();
    }

    /** Whether the plan is paused and not resumed yet. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(PlanPause::isOpen);
    }

    /** Whether a pause skips the plan date: it is on or after the day paused and before the day resumed. */
    public boolean isSkipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** Pauses the plan from the day. */
    public void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resumes the paused plan from the day. */
    public void resume(LocalDate on) {
        pauses.stream().filter(PlanPause::isOpen).forEach(p -> p.resume(on));
    }

    public LocalDate getEnd() {
        return end;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }

    /** Whether a claim has been made for the plan date. */
    public boolean hasMade(LocalDate date) {
        return made.contains(date);
    }

    public void markMade(LocalDate date) {
        made.add(date);
    }
}
